from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_closes = []
        self.bucket_valid = True

        self.current_slice = None

        self.entry_ticket = None
        self.pending_entry_symbol = None

        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None

        self.expiration_block_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self.current_slice = slice
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(current_date)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar)

        self._evaluate_held_position()

    def _process_minute_bar(self, bar: TradeBar):
        bar_time = bar.Time
        bar_date = bar_time.date()

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_date != bar_date or self.bucket_start != bucket_start:
            self.bucket_date = bar_date
            self.bucket_start = bucket_start
            self.bucket_closes = [float(bar.Close)]
            self.bucket_valid = True
            return

        expected_time = self.bucket_start + timedelta(minutes=len(self.bucket_closes))

        if bar_time != expected_time:
            self.bucket_valid = False

        self.bucket_closes.append(float(bar.Close))

        if len(self.bucket_closes) == 5:
            if self.bucket_valid:
                consolidated_close = self.bucket_closes[-1]
                consolidated_end = self.bucket_start + timedelta(minutes=5)
                self._process_five_minute_close(
                    consolidated_close,
                    consolidated_end
                )

    def _process_five_minute_close(self, close: float, bar_end: datetime):
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        spy_price = float(self.current_slice.Bars[self.spy].Close)
        self._attempt_entry(spy_price)

    def _attempt_entry(self, spy_price: float):
        chain = self.current_slice.OptionChains.get(self.option.Symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration "
                f"{selected_expiry}."
            )
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.pending_entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="ENTRY"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiration={selected_expiry}, strike={selected.Strike}"
        )

    def _evaluate_held_position(self):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if (
            self.Time.date() == self._previous_trading_day(expiry_date)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        if self.exit_ticket is not None and self._order_open(self.exit_ticket):
            return

        quote = self._get_current_option_quote(self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _get_current_option_quote(self, symbol):
        chain = self.current_slice.OptionChains.get(self.option.Symbol)

        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        quote_bar = self.current_slice.QuoteBars.get(symbol)
        if quote_bar is not None and quote_bar.Bid is not None and quote_bar.Ask is not None:
            return float(quote_bar.Bid.Close), float(quote_bar.Ask.Close)

        return None

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._order_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=f"EXIT: {reason}"
        )

        self.Debug(f"Exit submitted: {self.held_symbol}, reason={reason}")

    def _handle_expiration_processing(self, current_date):
        if self.held_symbol is not None:
            expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.expiration_block_date = current_date

                if self.entry_ticket is not None and self._order_open(self.entry_ticket):
                    self.entry_ticket.Cancel("Expiration processing")

                self._submit_exit("expiration processing")

        if self.expiration_block_date == current_date:
            return

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is not None
            and self._order_open(self.equity_liquidation_ticket)
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected ({quantity}); "
            "liquidating immediately."
        )

        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="UNEXPECTED EXERCISE/ASSIGNMENT LIQUIDATION"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if order_event.Symbol.SecurityType == SecurityType.Option:
                if (
                    order_event.OrderType == OrderType.OptionExercise
                    or getattr(order_event, "IsAssignment", False)
                ):
                    self.Debug(
                        f"Unexpected option exercise or assignment: "
                        f"{order_event.Symbol}"
                    )
                    self._handle_unexpected_equity_position()

            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.FillQuantity > 0
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price:.4f}"
                )

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(f"Exit filled: {order_event.Symbol}")
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.entry_ticket = None
            self.pending_entry_symbol = None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self._order_open(self.entry_ticket)
        )

    def _order_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while candidate.weekday() >= 5 or not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
