        self.held_option = None
        self.entry_price = None
        self.exit_ticket = None

        self.blocked_date = None
        self.spy_liquidation_pending = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Handle unexpected SPY equity created by exercise or assignment.
        if self.Portfolio[self.spy_symbol].Quantity != 0:
            self._liquidate_unexpected_spy()

        # Never intentionally hold an option into expiration.
        if (
            self.held_option is not None
            and self._date_of(self.held_option.ID.Date) <= current_date
        ):
            self.blocked_date = current_date
            self._submit_option_exit("expiration processing")

        self._evaluate_option_exit(slice)

        spy_bar = self._get_spy_bar(slice)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar, slice):
        bar_time = minute_bar.Time
        local_date = bar_time.date()
        minute_of_day = bar_time.hour * 60 + bar_time.minute

        # Only regular-session SPY bars are used.
        if minute_of_day < 9 * 60 + 30 or minute_of_day >= 16 * 60:
            return

        bucket_minute = 9 * 60 + 30 + (
            (minute_of_day - (9 * 60 + 30)) // 5
        ) * 5
        bucket_start = datetime(
            local_date.year,
            local_date.month,
            local_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.bucket_start is None or bucket_start != self.bucket_start:
            if self.bucket_start is not None:
                self._complete_five_minute_bar(slice)

            self.bucket_date = local_date
            self.bucket_start = bucket_start
            self.bucket_open = float(minute_bar.Open)
            self.bucket_high = float(minute_bar.High)
            self.bucket_low = float(minute_bar.Low)
            self.bucket_close = float(minute_bar.Close)
            self.bucket_volume = int(minute_bar.Volume)
            return

        self.bucket_high = max(self.bucket_high, float(minute_bar.High))
        self.bucket_low = min(self.bucket_low, float(minute_bar.Low))
        self.bucket_close = float(minute_bar.Close)
        self.bucket_volume += int(minute_bar.Volume)

    def _complete_five_minute_bar(self, slice):
        close = self.bucket_close
        bar_end = self.bucket_start + timedelta(minutes=5)

        self.closes.append(close)

        if len(self.closes) >= self.slow_period:
            fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            slow = sum(self.closes) / self.slow_period

            bullish_cross = (
                self.previous_fast is not None
                and self.previous_slow is not None
                and self.previous_fast <= self.previous_slow
                and fast > slow
            )

            if (
                bullish_cross
                and datetime(2000, 1, 1, 9, 45).time()
                <= bar_end.time()
                <= datetime(2000, 1, 1, 14, 30).time()
            ):
                self._evaluate_entry(slice, close, bar_end.date())

            self.previous_fast = fast
            self.previous_slow = slow

    def _evaluate_entry(self, slice, spy_price, algorithm_date):
        if self.blocked_date == algorithm_date:
            return

        if self.held_option is not None:
            return

        if self.entry_order_id is not None:
            return

        chains = self._get_option_chains(slice)
        if chains is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        eligible = []

        for chain in chains:
            for contract in chain:
                expiry_date = self._date_of(contract.Expiry)

                if expiry_date < algorithm_date + timedelta(days=7):
                    continue

                if contract.Right != OptionRight.Call:
                    continue

                if float(contract.Strike) < 1.01 * float(spy_price):
                    continue

                eligible.append(contract)

        if not eligible:
            self.Debug(
                "Skipped entry: no call contract met expiration and strike rules."
            )
            return

        nearest_expiry = min(self._date_of(c.Expiry) for c in eligible)
        same_expiry = [
            c for c in eligible
            if self._date_of(c.Expiry) == nearest_expiry
        ]

        selected = min(
            same_expiry,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_ticket = self.market_order(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={nearest_expiry} strike={selected.Strike}"
        )

    def _evaluate_option_exit(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiry_date = self._date_of(self.held_option.ID.Date)
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_option_exit("pre-expiration time stop")
            return

        if self.exit_ticket is not None:
            return

        contract = self._find_current_contract(slice, self.held_option)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_option_exit("50% profit target")

    def _submit_option_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.cancel("Replacing open option exit order")

        self.exit_ticket = self.market_order(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_option} ({reason})")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_option} "
                    f"price={self.entry_price}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ):
                if order_event.Status != OrderStatus.PartiallyFilled:
                    self.entry_order_id = None
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.held_option = None
                self.entry_price = None

            self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            f"Unexpected exercise or assignment: {assignment_event.Symbol}"
        )
        self.blocked_date = self.Time.date()
        self._liquidate_unexpected_spy()

    def _liquidate_unexpected_spy(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0 or self.spy_liquidation_pending:
            return

        self.blocked_date = self.Time.date()
        self.spy_liquidation_pending = True
        self.Debug("Liquidating unexpected SPY equity position.")
        self.market_order(
            self.spy_symbol,
            -quantity,
            tag="Unexpected exercise or assignment"
        )

    def _find_current_contract(self, slice, symbol):
        chains = self._get_option_chains(slice)
        if chains is None:
            return None

        for chain in chains:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract

        return None

    def _get_option_chains(self, slice):
        try:
            if slice.OptionChains is None:
                return None
            return slice.OptionChains.Values
        except Exception:
            try:
                return slice.OptionChains
            except Exception:
                return None

    def _get_spy_bar(self, slice):
        try:
            if slice.Bars is None:
                return None
            return slice.Bars[self.spy_symbol]
        except Exception:
            return None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while True:
            try:
                is_open = self.Securities[
                    self.spy_symbol
                ].Exchange.Hours.IsDateOpen(
                    datetime(
                        candidate.year,
                        candidate.month,
                        candidate.day
                    )
                )
            except Exception:
                is_open = candidate.weekday() < 5

            if is_open:
                return candidate

            candidate -= timedelta(days=1)

    @staticmethod
    def _date_of(value):
        try:
            return value.date()
        except Exception:
            return value
